const collectPayload = () => {
    const payload = [];
    const lists = qsa(".disc-list", wizard);
    lists.forEach((ul, listIndex) => {
      const lis = qsa("li", ul);
      lis.forEach((li, idx) => {
        payload.push({ list: listIndex, pos: idx, type: li.getAttribute("data-type") });
      });
    });
    return payload;
};

const score = (payload) => {
    const maj = [];
    const min = [];
    payload.forEach((x) => {
      if (x.pos === 0) maj.push(x.type);
      if (x.pos === 3) min.push(x.type);
    });
    const count = (arr, ch) => arr.reduce((a, v) => a + (v === ch ? 1 : 0), 0);
    return {
      d: count(maj, "d") - count(min, "d"),
      i: count(maj, "i") - count(min, "i"),
      s: count(maj, "s") - count(min, "s"),
      c: count(maj, "c") - count(min, "c"),
    };
};
```

So the per-list scoring is: item at position 0 (top, "Я наиболее (most like me)") → +1 to its type; item at position 3 (bottom, "Я наименее (least like me)") → −1 to its type. Middle positions (1, 2) don't count.

