```js
(() => {
  'use strict';

  const $ = (s, r) => (r || document).querySelector(s);
  const $$ = (s, r) => Array.prototype.slice.call((r || document).querySelectorAll(s));

  const wizard = $('#wizardmodal');
  const tabs = $$('.disc-tab', wizard);
  const panes = $$('.disc-pane', wizard);
  const btnPrev = $('[data-disc-prev]', wizard);
  const btnNext = $('[data-disc-next]', wizard);
  const btnFinish = $('[data-disc-finish]', wizard);
  const progressEl = $('#discProgress');
  const resultBox = $('#discResult');
  const scoreEl = $('#discScoreValue');
  const tabsScroller = $('.disc-modal__tabs', wizard);
  const wizardBody = $('.disc-modal__body', wizard);

  let step = 0;
  let finished = false;
  let lastFocus = null;
  let lastScore = null;

  const isCoarse = !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches);

  // ===== steps / render =====
  function centerActiveTab(behavior) {
    if (tabsScroller && tabsScroller.scrollWidth > tabsScroller.clientWidth + 2) {
      const active = tabs.find(t => Number(t.dataset.stepBtn) === step);
      if (active) {
        const cRect = tabsScroller.getBoundingClientRect();
        const tRect = active.getBoundingClientRect();
        const target = tabsScroller.scrollLeft + (tRect.left - cRect.left) + tRect.width / 2 - tabsScroller.clientWidth / 2;
        tabsScroller.scrollTo({ left: Math.max(0, target), behavior: behavior || 'smooth' });
      }
    }
  }

  function render() {
    tabs.forEach(t => {
      const is = Number(t.dataset.stepBtn) === step && !finished;
      t.classList.toggle('is-active', is);
      t.setAttribute('aria-selected', String(is));
    });
    panes.forEach(p => p.classList.toggle('is-active', !finished && Number(p.dataset.stepPane) === step));
    resultBox.classList.toggle('is-active', finished);
    btnPrev.disabled = step === 0;
    btnNext.hidden = step === 7 || finished;
    btnFinish.hidden = step !== 7 || finished;
    $$('.btn-result').forEach(b => b.hidden = !finished);
    progressEl.style.width = (finished ? 100 : ((step + 1) / 8) * 100) + '%';
    centerActiveTab('auto');
  }

  function setStep(n) {
    finished = false;
    step = Math.max(0, Math.min(7, n));
    render();
    requestAnimationFrame(() => wizardBody && wizardBody.scrollTo({ top: 0, behavior: 'smooth' }));
  }

  // ===== score (оригинальная логика: верх = +1, низ = -1) =====
  function collectPayload() {
    const payload = [];
    $$('.disc-list', wizard).forEach((ul) => {
      $$('li', ul).forEach((li, idx) => {
        payload.push({ pos: idx, type: li.getAttribute('data-type') });
      });
    });
    return payload;
  }
  function score(payload) {
    const maj = [], min = [];
    payload.forEach(x => { if (x.pos === 0) maj.push(x.type); if (x.pos === 3) min.push(x.type); });
    const count = (arr, ch) => arr.reduce((a, v) => a + (v === ch ? 1 : 0), 0);
    return { d: count(maj,'d')-count(min,'d'), i: count(maj,'i')-count(min,'i'), s: count(maj,'s')-count(min,'s'), c: count(maj,'c')-count(min,'c') };
  }
  function formatScore(sc) { return 'D:' + sc.d + ', I:' + sc.i + ', S:' + sc.s + ', C:' + sc.c; }
```

