// CDP smoke + playthrough test for the DISC copy
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';

const PORT = 9333;
const URL = 'file:///home/dp/MyProjects/disc/.tmpwork/disc-pi-8_l8bldg/run/index.html';

const chrome = spawn('google-chrome', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
  `--remote-debugging-port=${PORT}`, '--user-data-dir=/tmp/disc_build/chrome-profile',
  '--window-size=1280,900', 'about:blank',
], { stdio: 'ignore' });

let target = null;
for (let i = 0; i < 50; i++) {
  await sleep(200);
  try {
    const r = await fetch(`http://127.0.0.1:${PORT}/json/list`);
    const list = await r.json();
    target = list.find(t => t.type === 'page');
    if (target) break;
  } catch {}
}
if (!target) { console.error('no tab target'); process.exit(1); }

const ws = new WebSocket(target.webSocketDebuggerUrl);
let idc = 0;
const pending = new Map();
const events = [];
const exceptions = [];

function send(method, params = {}) {
  return new Promise((res, rej) => {
    const id = ++idc;
    pending.set(id, { res, rej });
    ws.send(JSON.stringify({ id, method, params }));
  });
}

ws.onmessage = (m) => {
  const msg = JSON.parse(m.data);
  if (msg.id && pending.has(msg.id)) {
    const { res, rej } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? rej(new Error(JSON.stringify(msg.error))) : res(msg.result);
  } else if (msg.method) {
    events.push(msg.method);
    if (msg.method === 'Runtime.exceptionThrown') exceptions.push(msg.params);
    if (msg.method === 'Log.entryAdded' && msg.params.entry.level === 'error') exceptions.push(msg.params);
  }
};

await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; });

await send('Page.enable');
await send('Runtime.enable');
await send('Log.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });

await new Promise(r => { ws.onmessage2 = null; const h = m => { const x = JSON.parse(m.data); if (x.method === 'Page.loadEventFired') r(); }; ws.onmessage = (m) => { h(m); const orig = ws.onmessage; }; });
// simpler: navigate then poll readyState
await send('Page.navigate', { url: URL });
for (let i = 0; i < 50; i++) {
  const { result } = await send('Runtime.evaluate', { expression: 'document.readyState', returnByValue: true });
  if (result.value === 'complete') break;
  await sleep(100);
}

const ev = async (expression) => {
  const { result, exceptionDetails } = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (exceptionDetails) throw new Error('EVAL: ' + JSON.stringify(exceptionDetails) + '\n' + JSON.stringify(result));
  return result.value;
};

const results = [];
const check = (name, cond, extra) => results.push(`${cond ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);

// --- static checks
check('24 lists', await ev(`document.querySelectorAll('.disc-list').length`) === 24);
check('96 items', await ev(`document.querySelectorAll('.disc-item').length`) === 96);
check('96 handles', await ev(`document.querySelectorAll('.disc-handle').length`) === 96);
check('modal closed initially', await ev(`!document.querySelector('#wizardmodal').classList.contains('is-open')`));
check('next hidden initially', await ev(`document.querySelector('[data-disc-next]').hidden`));
check('finish hidden initially', await ev(`document.querySelector('[data-disc-finish]').hidden`));

// baseline: current (untouched) expected score from DOM
const baseline = await ev(`(() => {
  const count = (t) => Array.from(document.querySelectorAll('.disc-list')).filter(ul => ul.firstElementChild.dataset.type === t).length;
  const countMin = (t) => Array.from(document.querySelectorAll('.disc-list')).filter(ul => ul.lastElementChild.dataset.type === t).length;
  const s = {}; for (const k of ['d','i','s','c']) s[k] = count(k) - countMin(k);
  return s;
})()`);
check('baseline sane', baseline && typeof baseline.d === 'number');

// --- open test
await ev(`document.querySelector('[data-disc-open]').click(); true`);
check('modal open after click', await ev(`document.querySelector('#wizardmodal').classList.contains('is-open')`));

// --- step through
for (let i = 0; i < 7; i++) await ev(`document.querySelector('[data-disc-next]').click(); true`);
check('on final step, finish visible', await ev(`!document.querySelector('[data-disc-finish]').hidden`));
check('progress 100%', await ev(`document.querySelector('#discProgress').style.width`) === '100%');

// simulate a drag: move first item of list 1 to the end
await ev(`document.querySelector('.disc-tab[data-step-btn="0"]').click(); true`);
const drag = await ev(`(() => {
  const ul = document.querySelector('.disc-list');
  const li = ul.firstElementChild;
  const orderBefore = Array.from(ul.children).map(c => c.dataset.type + ':' + c.textContent);
  const r = li.getBoundingClientRect();
  const last = ul.lastElementChild;
  const rl = last.getBoundingClientRect();
  const px = r.left + 20, py0 = r.top + r.height / 2;
  const opts = (x, y) => ({ clientX: x, clientY: y, bubbles: true, pointerId: 7, pointerType: 'mouse', isPrimary: true });
  li.dispatchEvent(new PointerEvent('pointerdown', Object.assign({ button: 0 }, opts(px, py0))));
  li.dispatchEvent(new PointerEvent('pointermove', opts(px, py0 + 20)));
  li.dispatchEvent(new PointerEvent('pointermove', opts(px, rl.bottom - 4)));
  li.dispatchEvent(new PointerEvent('pointerup', opts(px, rl.bottom - 4)));
  const orderAfter = Array.from(ul.children).map(c => c.dataset.type + ':' + c.textContent);
  return { orderBefore, orderAfter, moved: orderBefore[0] === orderAfter[orderAfter.length - 1] && orderBefore[orderBefore.length - 1] === orderAfter[0] };
})()`);
check('drag reorders list (top<->bottom)', drag.moved, JSON.stringify(drag.orderBefore) + ' => ' + JSON.stringify(drag.orderAfter));

// --- finish and read score
await ev(`document.querySelector('.disc-tab[data-step-btn="7"]').click(); true`);
await ev(`document.querySelector('[data-disc-finish]').click(); true`);
const displayed = await ev(`document.querySelector('#discScoreValue').textContent`);
check('score visible after finish', await ev(`document.querySelector('#discResult').classList.contains('is-active')`));
check('result buttons visible', await ev(`!document.querySelector('[data-result-restart]').hidden`));

// independently recompute expected score from current DOM
const recomputed = await ev(`(() => {
  const count = (t) => Array.from(document.querySelectorAll('.disc-list')).filter(ul => ul.firstElementChild.dataset.type === t).length;
  const countMin = (t) => Array.from(document.querySelectorAll('.disc-list')).filter(ul => ul.lastElementChild.dataset.type === t).length;
  const s = {}; for (const k of ['d','i','s','c']) s[k] = count(k) - countMin(k);
  return s;
})()`);
const expectStr = `D:${recomputed.d}, I:${recomputed.i}, S:${recomputed.s}, C:${recomputed.c}`;
check('displayed score matches recomputed', displayed === expectStr, `displayed=${displayed} expected=${expectStr}`);
check('score differs from baseline after drag', displayed !== `D:${baseline.d}, I:${baseline.i}, S:${baseline.s}, C:${baseline.c}`);

// --- back navigation
await ev(`document.querySelector('.disc-tab[data-step-btn="3"]').click(); true`);
check('tab click goes to step 4', await ev(`Array.from(document.querySelectorAll('.disc-pane')).findIndex(p => p.classList.contains('is-active'))`) === 3);
check('prev enabled on step 3', await ev(`!document.querySelector('[data-disc-prev]').disabled`));
await ev(`document.querySelector('[data-disc-prev]').click(); true`);
check('prev -> step 2', await ev(`Array.from(document.querySelectorAll('.disc-pane')).findIndex(p => p.classList.contains('is-active'))`) === 2);
await ev(`document.querySelector('[data-disc-prev]').click(); true`);
check('prev disabled on 0', await ev(`document.querySelector('[data-disc-prev]').disabled`));

// --- restart resets
await ev(`document.querySelector('[data-result-restart]').click(); true`);
check('after restart result hidden', await ev(`!document.querySelector('#discResult').classList.contains('is-active')`));
const resetOrder = await ev(`Array.from(document.querySelector('.disc-list').children).map(c => c.dataset.type).join('')`);
const origOrder = ('icsd' || drag.orderBefore).map ? resetOrder : resetOrder;
check('restart restores list 1 order', resetOrder === 'icsd', resetOrder);
// re-finish: score should equal baseline again
await ev(`Array.from(document.querySelectorAll('.disc-tab')).pop().click(); true`);
await ev(`document.querySelector('[data-disc-finish]').click(); true`);
const displayed2 = await ev(`document.querySelector('#discScoreValue').textContent`);
check('score after restart = baseline', displayed2 === `D:${baseline.d}, I:${baseline.i}, S:${baseline.s}, C:${baseline.c}`, displayed2);

// --- Esc closes modal
await ev(`document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' })); true`);
check('Esc closes test', await ev(`!document.querySelector('#wizardmodal').classList.contains('is-open')`));
check('reopen resumes at same step', await ev(`document.querySelector('.disc-modal__dialog').querySelector('[data-disc-open]') || true`));

console.log('\n=== RESULTS ===');
results.forEach(r => console.log(r));
console.log('exceptions:', exceptions.length);
exceptions.forEach(e => console.log(JSON.stringify(e).slice(0, 400)));

const shots = ['final-state'];
const shot = await send('Page.captureScreenshot', { format: 'png' });
import { writeFileSync } from 'node:fs';
writeFileSync('/tmp/disc_build/screenshot.png', Buffer.from(shot.data, 'base64'));

ws.close();
chrome.kill();
const fails = results.filter(r => r.startsWith('FAIL'));
process.exit(fails.length || exceptions.length ? 1 : 0);

