import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
import { writeFileSync } from 'node:fs';

const PORT = 9334;
const chrome = spawn('google-chrome', ['--headless=new','--no-sandbox','--disable-gpu','--disable-dev-shm-usage',`--remote-debugging-port=${PORT}`,'--user-data-dir=/tmp/disc_build/chrome2','about:blank'], { stdio: 'ignore' });
let target = null;
for (let i = 0; i < 60; i++) { await sleep(200); try { const l = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json(); target = l.find(t=>t.type==='page'); if (target) break; } catch {} }
const ws = new WebSocket(target.webSocketDebuggerUrl);
let idc=0; const pend=new Map();
const send=(m,p={})=>new Promise((res,rej)=>{const id=++idc;pend.set(id,{res,rej});ws.send(JSON.stringify({id,method:m,params:p}));});
ws.onmessage=m=>{const x=JSON.parse(m.data);if(x.id&&pend.has(x.id)){const{res,rej}=pend.get(x.id);pend.delete(x.id);x.error?rej(new Error(JSON.stringify(x.error))):res(x.result);}};
await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j;});
await send('Page.enable'); await send('Runtime.enable');
// try viewports
for (const [w,h] of [[1280,900],[800,600],[480,820]]) {
  await send('Emulation.setDeviceMetricsOverride', { width:w, height:h, deviceScaleFactor:1, mobile:false });
  await send('Page.navigate', { url: 'file:///home/dp/MyProjects/disc/.tmpwork/disc-pi-8_l8bldg/run/index.html' });
  for (let i=0;i<50;i++){ const {result}=await send('Runtime.evaluate',{expression:'document.readyState',returnByValue:true}); if(result.value==='complete')break; await sleep(100);}
  const ev=async e=>{const {result,exceptionDetails}=await send('Runtime.evaluate',{expression:e,returnByValue:true}); if(exceptionDetails) throw new Error(JSON.stringify(exceptionDetails)); return result.value;};
  const rep = await ev(`(() => {
    const R = el => { const r = el.getBoundingClientRect(); return [Math.round(r.left),Math.round(r.top),Math.round(r.width),Math.round(r.height)]; };
    const out = {};
    out.headerBtn = R(document.querySelector('.site-header .btn'));
    out.heroTitle = R(document.querySelector('.hero__title'));
    out.heroBtn = R(document.querySelector('.hero .btn'));
    out.features = R(document.querySelector('.hero__features'));
    out.scrollH = document.documentElement.scrollHeight;
    return out;
  })()`);
  await ev(`document.querySelector('[data-disc-open]').click(); true`);
  await sleep(150);
  const modal = await ev(`(() => {
    const R = el => { const r = el.getBoundingClientRect(); return [Math.round(r.left),Math.round(r.top),Math.round(r.width),Math.round(r.height)]; };
    const d = document.querySelector('.disc-modal__dialog');
    const vis = (r, w) => r[1] >= -1 && r[1] + r[3] <= w + 1 && r[0] >= -1 && r[0]+r[2] <= (innerWidth) + 1;
    return {
      dpr: devicePixelRatio,
      dialog: R(document.querySelector('.disc-modal__dialog')),
      viewport: [innerWidth, innerHeight],
      tabs: R(document.querySelector('.disc-modal__tabs')),
      close: R(document.querySelector('.disc-modal__close')),
      bodyVisible: R(document.querySelector('.disc-pane.is-active')),
      progress: R(document.querySelector('.disc-progress')),
      actions: R(document.querySelector('.disc-actions')),
      handle: R(document.querySelector('.disc-pane.is-active .disc-item .disc-handle')),
      firstItem: R(document.querySelector('.disc-pane.is-active .disc-item')),
      cards: Array.from(document.querySelectorAll('.disc-pane.is-active .disc-card')).map(R),
      grid: R(document.querySelector('.disc-grid3')),
      tabsOverflow: document.querySelector('.disc-modal__tabs').scrollWidth > document.querySelector('.disc-modal__tabs').clientWidth + 2,
      bodyScroll: document.querySelector('.disc-modal__body').scrollHeight > document.querySelector('.disc-modal__body').clientHeight,
    };
  })()`);
  // open result
  await ev(`Array.from(document.querySelectorAll('.disc-tab')).pop().click(); true`);
  await ev(`document.querySelector('[data-disc-finish]').click(); true`);
  await sleep(120);
  const res = await ev(`(() => {
    const R = el => { const r = el.getBoundingClientRect(); return [Math.round(r.left),Math.round(r.top),Math.round(r.width),Math.round(r.height)]; };
    return { score: R(document.querySelector('.disc-result__score')), buttons: R(document.querySelector('.disc-result__actions')), bodyScrollLeft: 0, bodyScrollTop: document.querySelector('.disc-modal__body').scrollTop, legend: R(document.querySelector('.disc-result__legend')) };
  })()`);
  console.log(`\n### viewport ${w}x${h}`);
  console.log('page:', JSON.stringify(rep));
  console.log('modal:', JSON.stringify(modal));
  console.log('result:', JSON.stringify(res));
  writeFileSync(`/tmp/disc_build/qa-${w}x${h}.png`, Buffer.from((await send('Page.captureScreenshot',{format:'png'})).data,'base64'));
}
ws.close(); chrome.kill();
EOF
